wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The requires clause guarantees len(text) <= 100000, so the text is
        // forwarded as-is to the only authority this node holds.
        let confirmation = response_channel::send(&reply.text);

        // The session identity comes from the host channel. The guest never
        // fabricates it. If the channel did not confirm delivery, or returned
        // no session, the node cannot meet its contract. Trapping is the
        // honest outcome in that case. Forging `delivered = true` or inventing
        // a session would not be.
        if !confirmation.delivered {
            panic!("response channel did not confirm delivery");
        }
        if confirmation.session.is_empty() {
            panic!("response channel returned no session identity");
        }

        DeliveryConfirmation {
            session: confirmation.session,
            delivered: confirmation.delivered,
        }
    }
}

export!(Node);
